<?php
$r=row('SELECT r.*,c.name category,c.family,c.slug,u.name FROM requests r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id WHERE r.id=?',[(int)($_GET['id']??0)]);
ensure($r && canReadRequest($u,$r),'No tiene acceso a esta solicitud.'); $snap=json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR);
$steps=rows('SELECT a.*,u.name assigned_name,v.name actor_name FROM approvals a JOIN users u ON u.id=a.assigned_user_id LEFT JOIN users v ON v.id=a.acted_by WHERE request_id=? ORDER BY revision DESC,step',[$r['id']]);
$periodState=$wf->periodState((int)$r['id']);
$next=row("SELECT * FROM approvals WHERE request_id=? AND revision=? AND status='waiting' ORDER BY step LIMIT 1",[$r['id'],$r['revision']]);
?>
<?php if(($r['slug']==='sufragar' || ($r['slug']==='jurado' && (json_decode($r['snapshot'],true)['jury_role']??'')!=='clavero'))): $electoralReport=ElectoralCertificate::report($r)??['status'=>'manual']; ?><section class="alert <?=ElectoralCertificate::needsManual($r)?'electoral-alert':'success'?>" role="alert"><h2><?=ElectoralCertificate::needsManual($r)?'Atención revisión manual obligatoria':'Certificado electoral leído por OCR'?></h2><p><?=e(ElectoralCertificate::summary($electoralReport))?></p><p>Revise el soporte original. El OCR no comprueba su autenticidad ante la Registraduría.</p></section><?php endif; ?>
<?php if($r['slug']==='jurado'): ?><p><strong>Modalidad:</strong> <?=e($snap['jury_role']??'Sin clasificar')?></p><?php endif; ?>
<div class="detail-banner"><div><span class="eyebrow">RADICADO</span><h2>TH-<?=str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)?></h2><p><?=e(familyLabel($r['family']).' · '.$r['category'])?></p></div><div class="detail-actions"><?=badge($r['status'])?><a class="button secondary" href="/?page=pdf&id=<?=(int)$r['id']?>"><?=icon('download')?> Descargar PDF con anexos</a></div></div>
<div class="detail-columns"><div><section class="panel form-panel"><h2>Datos y motivo</h2><div class="identity-grid"><div><span>Funcionario</span><strong><?=e($snap['name'])?></strong></div><div><span>Cédula</span><strong><?=e($snap['identification'])?></strong></div><div><span>Cargo</span><strong><?=e($snap['job_title'])?></strong></div><div><span>Dependencia</span><strong><?=e($snap['department'])?></strong></div></div><h3>Justificación</h3><p class="preserve"><?=e($r['justification'])?></p><?php if($r['exception_reason']): ?><h3>Excepción de anticipación</h3><p class="preserve"><?=e($r['exception_reason'])?></p><?php endif; if($r['relationship']): ?><p><strong>Parentesco:</strong> <?=e($r['relationship'])?></p><?php endif; ?><p class="fine">Registrada el <?=e($r['created_at'])?> · Revisión <?=(int)$r['revision']?>. Los datos del funcionario corresponden al momento del envío.</p></section>
<section class="panel"><div class="panel-header"><h2>Fechas y duración</h2><strong><?=e(hours((int)$r['total_minutes']))?></strong></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Desde</th><th>Hasta</th><th>Tiempo laborable</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM request_slots WHERE request_id=? ORDER BY date,start_time',[$r['id']]) as $s): ?><tr><td><?=e($s['date'])?></td><td><?=e($s['start_at']??$s['start_time'])?></td><td><?=e($s['end_at']??$s['end_time'])?></td><td><?=e(hours((int)$s['minutes']))?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($r['birthday_year']): ?><section class="panel form-panel"><h2>Beneficio de Cumpleaños</h2><p>Vigencia a la que se carga: <?=(int)$r['birthday_year']?> · Una jornada completa.</p></section><?php endif; ?><section class="panel form-panel"><h2>Soportes y actos asociados</h2><?php foreach(rows('SELECT * FROM attachments WHERE request_id=? OR act_id IN (SELECT act_id FROM allocations WHERE request_id=?) ORDER BY id',[$r['id'],$r['id']]) as $a): ?><a class="attachment" href="/?page=download&id=<?=(int)$a['id']?>"><?=icon('file')?><span><?=e($a['original_name'])?><small><?=number_format((int)$a['size']/1024,0,',','.')?> KB · <?=e($a['mime'])?></small></span><?=icon('download')?></a><?php endforeach; foreach(rows('SELECT a.number,l.* FROM allocations l JOIN acts a ON a.id=l.act_id WHERE request_id=?',[$r['id']]) as $a): ?><p><strong><?=e($a['number'])?></strong> · <?=e(hours((int)$a['minutes']))?> · <?=e(statusLabel($a['state']))?><?php if((int)$a['returned_minutes']): ?> · Reintegrado: <?=e(hours((int)$a['returned_minutes']))?><?php endif; ?></p><?php endforeach; ?></section>
<section class="panel form-panel"><h2>Historial del trámite</h2><ol class="timeline"><?php foreach(rows('SELECT e.*,u.name FROM events e JOIN users u ON u.id=e.actor_id WHERE request_id=? ORDER BY e.id DESC',[$r['id']]) as $ev): ?><li><strong><?=e($ev['action'])?></strong><span><?=e($ev['name'].' · '.$ev['created_at'])?></span><p><?=e($ev['detail'])?></p></li><?php endforeach; ?></ol></section></div>
<aside><section class="panel form-panel"><h2>Aprobaciones</h2><ol class="timeline"><?php foreach($steps as $s): ?><li><span>Revisión <?=(int)$s['revision']?> · Etapa <?=(int)$s['step']?></span><strong><?=e(['manager'=>'Jefe inmediato','subsecretary'=>'Subsecretario','mayor'=>'Alcalde'][$s['role']])?></strong><p><?=e($s['actor_name']??$s['assigned_name'])?></p><?=badge($s['status'])?><?php if($s['acted_at']): ?><small><?=e($s['acted_at'])?></small><?php endif; if($s['comment']): ?><p><?=e($s['comment'])?></p><?php endif; ?></li><?php endforeach; ?></ol></section>
<?php if($r['status']==='pending' && $next && (int)$next['assigned_user_id']===(int)$u['id']): ?><section class="panel form-panel"><h2>Tu decisión</h2><p class="muted">Revisa los datos y soportes antes de decidir.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><?php if($periodState==='ongoing'): ?><div class="alert warning">El disfrute ya comenzó. Esta aprobación quedará registrada como excepcional.</div><label>Justificación de la aprobación excepcional<textarea name="approval_exception_reason" maxlength="2500" rows="3" placeholder="Obligatoria al aprobar: explica el retraso o la urgencia."><?=e($_POST['approval_exception_reason']??'')?></textarea></label><?php elseif($periodState==='ended'): ?><div class="alert warning">El periodo de disfrute ya terminó. La aprobación está bloqueada.</div><?php endif; ?><?php if(($r['slug']==='sufragar' || ($r['slug']==='jurado' && (json_decode($r['snapshot'],true)['jury_role']??'')!=='clavero')) && ElectoralCertificate::needsManual($r)): ?><div class="alert electoral-alert"><strong>Antes de aprobar debe revisar manualmente el certificado electoral.</strong><label>Constancia de revisión manual<textarea name="electoral_review" maxlength="1500" rows="3" placeholder="Verifique cédula, fecha de elecciones y disfrute dentro del plazo aplicable: 30 días calendario para sufragar o 45 días hábiles para jurado."><?=e($_POST['electoral_review']??'')?></textarea></label><p>Registre entre 10 y 1.500 caracteres al aprobar. Para devolver o rechazar basta con la observación de la decisión.</p></div><?php endif; ?><label>Observación<textarea name="comment" maxlength="3000" rows="4" placeholder="Obligatoria para devolver o rechazar."></textarea></label><div class="stack-buttons"><button class="button" name="decision" value="approved" <?=$periodState==='ended'?'disabled':''?>>Aprobar solicitud</button><button class="button secondary" name="decision" value="returned">Devolver para corrección</button><button class="button danger" name="decision" value="rejected">Rechazar definitivamente</button></div></form></section><?php endif; ?>
<?php if($r['status']==='cancel_pending'): ?><section class="panel form-panel"><h2>Cancelación solicitada</h2><p><?=e($r['cancellation_reason'])?></p><?php try { $canCancel=(int)$r['cancellation_assignee_id']===(int)$u['id']; } catch(DomainException) { $canCancel=false; } if($canCancel): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="review_cancel"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Motivo de la decisión<textarea name="comment" required minlength="5" maxlength="3000"></textarea></label><p class="fine">Al autorizar se reintegrará solo el tiempo no disfrutado hasta la fecha y hora de la decisión.</p><button class="button" name="decision" value="approve">Autorizar cancelación</button><button class="button secondary" name="decision" value="deny">Denegar cancelación</button></form><?php endif; ?></section><?php endif; ?>
<?php if((int)$r['user_id']===(int)$u['id']): if($r['status']==='returned'): ?><a class="button full" href="/?page=new&id=<?=(int)$r['id']?>">Corregir y reenviar</a><?php endif; if(in_array($r['status'],['pending','returned','approved'],true)): ?><section class="panel form-panel"><h2>Cancelar solicitud</h2><p class="fine"><?=$r['status']==='approved'?'La cancelación requiere autorización del subsecretario.':'Se liberarán las reservas de esta solicitud.'?></p><form method="post" data-confirm="¿Deseas continuar con la cancelación de esta solicitud?"><?=csrf()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Motivo<textarea name="comment" required minlength="5" maxlength="3000"></textarea></label><button class="button secondary">Solicitar cancelación</button></form></section><?php endif; endif; ?></aside></div>
